import{_ as o,C as e,o as b,c as i,E as a,a2 as c}from"./chunks/framework.Bx6eOp9J.js";const _=JSON.parse('{"title":"审批记录存了动作，放行时是否真的比较？","description":"","frontmatter":{"title":"审批记录存了动作，放行时是否真的比较？","date":"2026-11-08","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"审批阶段是否把恢复请求的目标与参数绑定到获批动作？","summary":"固定源码的隔离实验中，改变请求编号、目标或参数仍得到审批阶段放行。结果只定位了本阶段的载荷绑定边界；调用方、恢复令牌、其他策略与最终效果仍需分别核验。","sources":["https://github.com/GoetzKohlberg/sidjua/tree/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2","https://github.com/OpenBMB/ChatDev/tree/464a681ba7bda869db97a50c5fa707c9a0fb57a0"],"pageClass":"runtime-v6-article","item_id":"SIG-20261108-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-08-sig-20261108-002-2026-11-08-approval-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-08-sig-20261108-002.md","filePath":"zh/engineering/2026-11-08-sig-20261108-002.md","lastUpdated":1794140260000}'),l={name:"zh/engineering/2026-11-08-sig-20261108-002.md"};function n(s,t,h,p,u,g){const r=e("ArticleCover"),d=e("ArticleTableScroll");return b(),i("div",null,[a(r,{image:"/assets/covers/daily-2026-11-08-sig-20261108-002-2026-11-08-approval-cover.png",kicker:"研究成果",title:"审批记录存了动作，放行时是否真的比较？",summary:"固定源码的隔离实验中，改变请求编号、目标或参数仍得到审批阶段放行。结果只定位了本阶段的载荷绑定边界；调用方、恢复令牌、其他策略与最终效果仍需分别核验。",version:"2026-11-08",languageHref:"/en/engineering/2026-11-08-sig-20261108-002",languageLabel:"English"}),a(d,{language:"zh"}),t[0]||(t[0]=c('<h1 id="审批记录存了动作-放行时是否真的比较" tabindex="-1">审批记录存了动作，放行时是否真的比较？ <a class="header-anchor" href="#审批记录存了动作-放行时是否真的比较" aria-label="Permalink to &quot;审批记录存了动作，放行时是否真的比较？&quot;">​</a></h1><p>一条审批记录既保存请求编号，也保存动作内容，这能保证恢复执行时仍是同一个动作吗？关键在于放行时比较什么。本次内部隔离实验中，代理身份与工作流保持不变，单独更换请求编号、目标或参数，审批阶段仍然放行。</p><p>这个结果提供了一项具体检查方法：把“记录里有这个字段”与“决策用这个字段做了约束”分开核验。它还没有回答完整系统能否执行变更动作；恢复令牌、调用方和其他策略阶段都可能阻止它。</p><h2 id="保存下来的动作-未必进入匹配条件" tabindex="-1">保存下来的动作，未必进入匹配条件 <a class="header-anchor" href="#保存下来的动作-未必进入匹配条件" aria-label="Permalink to &quot;保存下来的动作，未必进入匹配条件&quot;">​</a></h2><p>SIDJUA（智能体治理软件）的被检查实现会保存动作的结构化内容与请求编号。但固定版本的审批查询按代理、工作流、记录状态和时间窗口选择记录，没有在该查询中比较请求编号或动作载荷。注释提到请求元数据匹配与兼容回退，实际实现中未见相应比较及回退分支。这是针对指定源码的观察，不是全仓库安全审计。<a href="https://github.com/GoetzKohlberg/sidjua/blob/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/approval.ts" target="_blank" rel="noreferrer">审批源码</a></p><p>动作类型、目标和可选参数属于动作描述，请求编号则是另一个字段。因此，“请求编号没变”也不能单独代替载荷不变性。反过来，即使记录中保存了完整载荷，若选择批准记录的条件不使用它，持久化本身也不会自动形成比较约束。<a href="https://github.com/GoetzKohlberg/sidjua/blob/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/types/pipeline.ts" target="_blank" rel="noreferrer">请求类型定义</a></p><h2 id="单独改变三个字段-会发生什么" tabindex="-1">单独改变三个字段，会发生什么 <a class="header-anchor" href="#单独改变三个字段-会发生什么" aria-label="Permalink to &quot;单独改变三个字段，会发生什么&quot;">​</a></h2><p>同日分析阶段执行了固定源码导出的隔离审批阶段。环境为 Node.js（服务端脚本运行环境）v24.19.0，数据库是 SQLite（嵌入式关系数据库）的真实内存实例，表结构仅服务于实验夹具。程序移除了导入并擦除类型标注，保留函数逻辑与查询；匹配器采用精确相等替身，日志器不做输出，条件解析分支没有使用。</p><p>在同一代理与精确匹配的工作流下，实验先写入一条有效的已批准记录，然后每次只改变一个输入字段。以下是内部实验记录的结果，不是新开展的完整恢复流程测试。<a href="/joinwell52/assets/evidence/2026-11-08-sig-20261108-002/approval-probe.json">完整实验记录</a></p><table tabindex="0"><thead><tr><th>相对原请求的变化</th><th>审批阶段结果</th><th>直接支持的判断</th></tr></thead><tbody><tr><td>不改变</td><td>放行</td><td>基准输入可匹配有效批准</td></tr><tr><td>仅更换请求编号</td><td>放行</td><td>此阶段未按原请求编号区分</td></tr><tr><td>仅更换目标</td><td>放行</td><td>此阶段未按原目标区分</td></tr><tr><td>仅更换参数</td><td>放行</td><td>此阶段未按原参数区分</td></tr><tr><td>仅更换代理</td><td>暂停</td><td>代理条件在此夹具中产生区分</td></tr><tr><td>使用拒绝记录</td><td>阻断</td><td>拒绝对照产生阻断结果</td></tr><tr><td>使用过期记录</td><td>暂停</td><td>时间窗口对照产生暂停结果</td></tr></tbody></table><p>前三项变化把静态查询观察变成了有对照的阶段行为证据。不同代理、拒绝和过期的结果也说明，实验并非把所有输入都写成无条件放行。然而，这些对照没有覆盖并发审批、拒绝优先级或生产数据库的完整约束，不能据此宣称审批系统整体可靠或整体失效。</p><h2 id="恢复令牌仍是另一道检查" tabindex="-1">恢复令牌仍是另一道检查 <a class="header-anchor" href="#恢复令牌仍是另一道检查" aria-label="Permalink to &quot;恢复令牌仍是另一道检查&quot;">​</a></h2><p>被读到的恢复代码用请求编号和审批编号生成消息认证码，校验后再把传入请求交给策略管线重评。签名内容不包含目标与参数；但这不等于本次实验已经绕过签名。实验没有执行令牌生成、校验或完整恢复路径，更没有产生任何文件删除或外部副作用。<a href="https://github.com/GoetzKohlberg/sidjua/blob/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/resume.ts" target="_blank" rel="noreferrer">恢复源码</a></p><p>因此，更换请求编号在隔离审批阶段放行，不能外推为更换编号后仍可通过恢复令牌。目标或参数变更能否到达该阶段，也依赖调用方是否保留原始获批对象。完整管线还有其他治理阶段；它们可能拒绝请求。管线遇到意外错误会返回阻断，但审计写入属于尽力而为的行为，阻断结果本身也不保证已有持久审计行。<a href="https://github.com/GoetzKohlberg/sidjua/blob/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/index.ts" target="_blank" rel="noreferrer">管线源码</a></p><p>这给出了对实验最重要的替代解释：若调用方严格保持获批动作不可变，阶段查询没有重复比较某字段，可能并不产生可利用的替换路径。现有证据尚未检验这一前提。</p><h2 id="人的回复与动作批准-承担不同责任" tabindex="-1">人的回复与动作批准，承担不同责任 <a class="header-anchor" href="#人的回复与动作批准-承担不同责任" aria-label="Permalink to &quot;人的回复与动作批准，承担不同责任&quot;">​</a></h2><p>ChatDev（多智能体开发框架）的已读人工节点路径提供一个有用但有限的对照：它为节点、说明和上下文请求人的输入，再把返回内容交给下游。提示服务使用锁串行请求通道，附加可选会话元数据，并记录交互。它检查的是内容交互路径，与持久化审批决定和签名恢复记录不是同一种对象。<a href="https://github.com/OpenBMB/ChatDev/blob/464a681ba7bda869db97a50c5fa707c9a0fb57a0/runtime/node/executor/human_executor.py" target="_blank" rel="noreferrer">人工节点源码</a>、<a href="https://github.com/OpenBMB/ChatDev/blob/464a681ba7bda869db97a50c5fa707c9a0fb57a0/utils/human_prompt.py" target="_blank" rel="noreferrer">提示服务源码</a></p><p>这个比较不构成安全排名，也不能由提示服务文件未展示审查者认证，就断言整个产品没有认证。它提醒工程师先界定人的输入究竟是内容、建议还是对某个不可变动作的许可，再选择相应的验证对象。</p><h2 id="让同一个变更案例走完责任链" tabindex="-1">让同一个变更案例走完责任链 <a class="header-anchor" href="#让同一个变更案例走完责任链" aria-label="Permalink to &quot;让同一个变更案例走完责任链&quot;">​</a></h2><p>根据上述观察，本文建议把单字段变化作为一条贯穿测试，而非在某处看到签名或审批日志就结束检查。下面是建议的核验责任链；除已明确执行的阶段实验，其余均是待验证项。</p><table tabindex="0"><thead><tr><th>位置</th><th>应检查的输入与责任</th><th>遇到什么应停止或重新决定</th><th>当前证据</th></tr></thead><tbody><tr><td>调用方</td><td>提交原始获批动作，保持身份、目标和参数对应</td><td>获批载荷无法确定</td><td>未执行</td></tr><tr><td>恢复入口</td><td>检验令牌与请求、审批记录的关系</td><td>令牌无效或归属不符</td><td>已读源码，未执行</td></tr><tr><td>审批阶段</td><td>依据匹配条件选择有效决定</td><td>无批准则暂停，拒绝则阻断</td><td>已执行本次隔离实验</td></tr><tr><td>其他策略</td><td>按当前权限与策略重评传入动作</td><td>当前策略不许可</td><td>已读管线，未执行集成测试</td></tr><tr><td>效果执行方</td><td>消费获批动作并记录实际效果</td><td>效果与许可不符、重复消费或前置状态冲突</td><td>未执行</td></tr></tbody></table><p>这不是对现有产品已经实现上述全部控制的描述。它把下一步需要补证的位置具体化，尤其避免用交互日志代替许可、用有效签名代替完整载荷绑定、用阶段放行代替效果已经发生。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的直接实现依据来自两个维护方的固定源码：前述治理软件提交 747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2，以及前述开发框架提交 464a681ba7bda869db97a50c5fa707c9a0fb57a0。它们属于公开实现证据；本次 2026-11-08 的<a href="/joinwell52/assets/evidence/2026-11-08-sig-20261108-002/approval-probe.json">隔离阶段记录</a>属于内部实验依据，包含环境、源文件哈希、输入、结果和替身范围。没有第三方独立复现来验证本文的阶段结论，更没有对完整系统的独立安全评估。封面只表达局部绑定关系，不表现真实副作用。</p><h2 id="还不能下判断的部分" tabindex="-1">还不能下判断的部分 <a class="header-anchor" href="#还不能下判断的部分" aria-label="Permalink to &quot;还不能下判断的部分&quot;">​</a></h2><p>本次没有执行实际仓库数据库模式、条件解析、密码辅助函数、并发决定、进程重启或最终效果，也没有验证完整调用图。因此不能将结果作为漏洞公告、利用复现或产品缺陷定论。</p><p>后续需要回答：每个调用方是否保留原始获批载荷？前置状态改变后如何使旧批准失效？同一批准能否仅消费一次，网络重试与重新批准如何区分？冲突决定、撤销、过期和策略修订在重启后由谁裁决？应用层拒绝之外，宿主权限是否另有约束？只有把这些问题与真实调用、记录和效果逐项对应，才能从阶段边界推进到系统层面的判断。</p>',27))])}const f=o(l,[["render",n]]);export{_ as __pageData,f as default};
